CREATE UNIQUE INDEX preview_effect_request_binding ON preview_effects(operation_id,request_hash);
CREATE TABLE preview_access_policies(project_id TEXT NOT NULL REFERENCES projects(project_id),gateway_id TEXT NOT NULL,principal_id TEXT NOT NULL,configuration_hash TEXT NOT NULL,policy_json TEXT NOT NULL CHECK(json_valid(policy_json)),created_at TEXT NOT NULL,PRIMARY KEY(project_id,gateway_id)) STRICT;
CREATE TABLE preview_write_gates(dataset_id TEXT PRIMARY KEY,project_id TEXT NOT NULL,dataset_operation_id TEXT NOT NULL,dataset_request_hash TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('OPEN','CLOSED')),fence INTEGER NOT NULL CHECK(fence>=0),revision INTEGER NOT NULL CHECK(revision>=0),close_operation_id TEXT REFERENCES preview_write_closures(operation_id),close_request_hash TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,FOREIGN KEY(project_id,dataset_id) REFERENCES datasets(project_id,dataset_id),FOREIGN KEY(dataset_operation_id,dataset_request_hash) REFERENCES preview_effects(operation_id,request_hash),CHECK((state='OPEN' AND close_operation_id IS NULL AND close_request_hash IS NULL) OR (state='CLOSED' AND close_operation_id IS NOT NULL AND close_request_hash IS NOT NULL))) STRICT;
CREATE TABLE preview_write_closures(operation_id TEXT PRIMARY KEY,dataset_id TEXT NOT NULL REFERENCES preview_write_gates(dataset_id),request_hash TEXT NOT NULL,request_json TEXT NOT NULL CHECK(json_valid(request_json)),created_at TEXT NOT NULL) STRICT;
CREATE TABLE preview_write_gate_events(dataset_id TEXT NOT NULL REFERENCES preview_write_gates(dataset_id),revision INTEGER NOT NULL,snapshot_json TEXT NOT NULL CHECK(json_valid(snapshot_json)),created_at TEXT NOT NULL,PRIMARY KEY(dataset_id,revision)) STRICT;
CREATE TABLE preview_access_requests(sequence INTEGER PRIMARY KEY,access_request_id TEXT NOT NULL UNIQUE,project_id TEXT NOT NULL,preview_id TEXT NOT NULL,dataset_id TEXT NOT NULL REFERENCES preview_write_gates(dataset_id),gateway_id TEXT NOT NULL,configuration_hash TEXT NOT NULL,subject_principal_id TEXT NOT NULL,intent_hash TEXT NOT NULL,request_hash TEXT NOT NULL,request_json TEXT NOT NULL CHECK(json_valid(request_json)),is_write INTEGER NOT NULL CHECK(is_write IN (0,1)),state TEXT NOT NULL CHECK(state IN ('PREPARED','DISPATCHED','UNKNOWN','FINISHED','NOT_SENT')),revision INTEGER NOT NULL CHECK(revision>=0),observation_json TEXT CHECK(observation_json IS NULL OR json_valid(observation_json)),created_at TEXT NOT NULL,dispatched_at TEXT,finished_at TEXT,FOREIGN KEY(project_id,preview_id) REFERENCES previews(project_id,preview_id),FOREIGN KEY(project_id,dataset_id) REFERENCES datasets(project_id,dataset_id),FOREIGN KEY(project_id,gateway_id) REFERENCES preview_access_policies(project_id,gateway_id),CHECK((state IN ('FINISHED','NOT_SENT'))=(finished_at IS NOT NULL)),CHECK((state='PREPARED')=(dispatched_at IS NULL))) STRICT;
CREATE TABLE preview_access_request_events(access_request_id TEXT NOT NULL REFERENCES preview_access_requests(access_request_id),revision INTEGER NOT NULL,snapshot_json TEXT NOT NULL CHECK(json_valid(snapshot_json)),created_at TEXT NOT NULL,PRIMARY KEY(access_request_id,revision)) STRICT;
CREATE INDEX preview_access_pending_writes ON preview_access_requests(dataset_id,is_write,state);
CREATE INDEX preview_access_recovery ON preview_access_requests(project_id,gateway_id,state,sequence);
CREATE TRIGGER preview_access_policy_update BEFORE UPDATE ON preview_access_policies BEGIN SELECT RAISE(ABORT,'PREVIEW_ACCESS_POLICY_IMMUTABLE'); END;
CREATE TRIGGER preview_access_policy_delete BEFORE DELETE ON preview_access_policies BEGIN SELECT RAISE(ABORT,'PREVIEW_ACCESS_POLICY_IMMUTABLE'); END;
CREATE TRIGGER preview_write_gate_update BEFORE UPDATE ON preview_write_gates WHEN OLD.state='CLOSED' OR NEW.dataset_id IS NOT OLD.dataset_id OR NEW.project_id IS NOT OLD.project_id OR NEW.dataset_operation_id IS NOT OLD.dataset_operation_id OR NEW.dataset_request_hash IS NOT OLD.dataset_request_hash OR NEW.created_at IS NOT OLD.created_at OR NEW.state<>'CLOSED' OR NEW.fence<>OLD.fence+1 OR NEW.revision<>OLD.revision+1 BEGIN SELECT RAISE(ABORT,'PREVIEW_WRITE_GATE_IMMUTABLE'); END;
CREATE TRIGGER preview_write_gate_delete BEFORE DELETE ON preview_write_gates BEGIN SELECT RAISE(ABORT,'PREVIEW_WRITE_GATE_RETAINED'); END;
CREATE TRIGGER preview_write_closure_update BEFORE UPDATE ON preview_write_closures BEGIN SELECT RAISE(ABORT,'PREVIEW_WRITE_CLOSURE_IMMUTABLE'); END;
CREATE TRIGGER preview_write_closure_delete BEFORE DELETE ON preview_write_closures BEGIN SELECT RAISE(ABORT,'PREVIEW_WRITE_CLOSURE_IMMUTABLE'); END;
CREATE TRIGGER preview_write_gate_event_update BEFORE UPDATE ON preview_write_gate_events BEGIN SELECT RAISE(ABORT,'PREVIEW_WRITE_GATE_EVENT_IMMUTABLE'); END;
CREATE TRIGGER preview_write_gate_event_delete BEFORE DELETE ON preview_write_gate_events BEGIN SELECT RAISE(ABORT,'PREVIEW_WRITE_GATE_EVENT_IMMUTABLE'); END;
CREATE TRIGGER preview_access_request_update BEFORE UPDATE ON preview_access_requests WHEN OLD.state IN ('FINISHED','NOT_SENT') OR NEW.access_request_id IS NOT OLD.access_request_id OR NEW.sequence<>OLD.sequence OR NEW.project_id IS NOT OLD.project_id OR NEW.preview_id IS NOT OLD.preview_id OR NEW.dataset_id IS NOT OLD.dataset_id OR NEW.gateway_id IS NOT OLD.gateway_id OR NEW.configuration_hash IS NOT OLD.configuration_hash OR NEW.subject_principal_id IS NOT OLD.subject_principal_id OR NEW.intent_hash IS NOT OLD.intent_hash OR NEW.request_hash IS NOT OLD.request_hash OR NEW.request_json IS NOT OLD.request_json OR NEW.is_write<>OLD.is_write OR NEW.created_at IS NOT OLD.created_at OR NEW.revision<>OLD.revision+1 OR (OLD.dispatched_at IS NOT NULL AND NEW.dispatched_at IS NOT OLD.dispatched_at) OR NOT ((OLD.state='PREPARED' AND NEW.state='DISPATCHED') OR (OLD.state='DISPATCHED' AND NEW.state IN ('UNKNOWN','FINISHED','NOT_SENT')) OR (OLD.state='UNKNOWN' AND NEW.state IN ('UNKNOWN','FINISHED'))) BEGIN SELECT RAISE(ABORT,'PREVIEW_ACCESS_REQUEST_IMMUTABLE'); END;
CREATE TRIGGER preview_access_request_delete BEFORE DELETE ON preview_access_requests BEGIN SELECT RAISE(ABORT,'PREVIEW_ACCESS_REQUEST_RETAINED'); END;
CREATE TRIGGER preview_access_request_event_update BEFORE UPDATE ON preview_access_request_events BEGIN SELECT RAISE(ABORT,'PREVIEW_ACCESS_REQUEST_EVENT_IMMUTABLE'); END;
CREATE TRIGGER preview_access_request_event_delete BEFORE DELETE ON preview_access_request_events BEGIN SELECT RAISE(ABORT,'PREVIEW_ACCESS_REQUEST_EVENT_IMMUTABLE'); END;
